import{_ as t,o as s,c as n,ah as r}from"./chunks/framework.BsNNkeaH.js";const d=JSON.parse('{"title":"Cantine et transport","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/vie-scolaire/cantine-et-transport.md","filePath":"src/guide/vie-scolaire/cantine-et-transport.md"}'),a={name:"guide/vie-scolaire/cantine-et-transport.md"};function o(i,e,l,u,c,p){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="cantine-et-transport" tabindex="-1">Cantine et transport <a class="header-anchor" href="#cantine-et-transport" aria-label="Permalink to &quot;Cantine et transport&quot;">​</a></h1><p>Cette page couvre la gestion de la cantine (menus et pointage) et le suivi du transport scolaire (affectation des élèves aux circuits et pointage des présences). Les circuits de transport eux-mêmes sont créés par l&#39;administrateur ; en tant que vie scolaire, vous affectez les élèves aux circuits existants et pointez leur présence à la montée et à la descente.</p><h2 id="gerer-les-menus-de-cantine" tabindex="-1">Gérer les menus de cantine <a class="header-anchor" href="#gerer-les-menus-de-cantine" aria-label="Permalink to &quot;Gérer les menus de cantine&quot;">​</a></h2><ol><li>Ouvrez <strong>Services aux élèves → Menus de cantine</strong>, puis cliquez sur <strong>Nouveau menu</strong>.</li><li>Choisissez le <strong>Site</strong> et la <strong>Date</strong> concernés.</li><li>Décrivez le contenu dans <strong>Menu</strong>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>La liste des menus se filtre par site. <strong>Modifier</strong> permet de corriger la date ou le contenu d&#39;un menu déjà publié ; <strong>Supprimer</strong> l&#39;efface définitivement après confirmation — action irréversible.</p><h2 id="pointer-les-presences-a-la-cantine" tabindex="-1">Pointer les présences à la cantine <a class="header-anchor" href="#pointer-les-presences-a-la-cantine" aria-label="Permalink to &quot;Pointer les présences à la cantine&quot;">​</a></h2><p><strong>Services aux élèves → Pointage cantine</strong> affiche, pour la date sélectionnée en haut de page (le jour en cours par défaut), la liste des élèves actuellement abonnés à la cantine. Pour chacun, touchez <strong>A mangé</strong> ou <strong>Absent</strong>, puis cliquez sur <strong>Enregistrer</strong> pour valider tout le pointage du jour en une fois. Si aucun élève n&#39;est abonné, la page l&#39;indique.</p><div class="tip custom-block"><p class="custom-block-title">Un pointage pensé pour le téléphone</p><p>Chaque élève a son bouton <strong>A mangé</strong> / <strong>Absent</strong> ; tout le monde est <strong>A mangé</strong> par défaut, et le bouton <strong>Tous ont mangé</strong> remet toute la liste à ce statut. Les compteurs en haut de liste se mettent à jour à chaque clic, et la barre du bas signale « Modifications non enregistrées » tant que vous n&#39;avez pas cliqué sur <strong>Enregistrer</strong> — quitter la page ou changer de date à ce moment-là demande confirmation. Un pointage ne peut pas être saisi pour une date future.</p></div><h2 id="affecter-des-eleves-aux-circuits-de-transport" tabindex="-1">Affecter des élèves aux circuits de transport <a class="header-anchor" href="#affecter-des-eleves-aux-circuits-de-transport" aria-label="Permalink to &quot;Affecter des élèves aux circuits de transport&quot;">​</a></h2><ol><li>Ouvrez <strong>Services aux élèves → Affectations aux circuits</strong>, puis cliquez sur <strong>Nouvelle affectation</strong>.</li><li>Choisissez l&#39;<strong>Élève</strong> (seuls les élèves pas encore affectés à un circuit sont proposés) puis le <strong>Circuit</strong> de transport.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>La liste des affectations se filtre par circuit. <strong>Retirer</strong> désaffecte un élève de son circuit après confirmation.</p><h2 id="pointer-les-presences-au-transport" tabindex="-1">Pointer les présences au transport <a class="header-anchor" href="#pointer-les-presences-au-transport" aria-label="Permalink to &quot;Pointer les présences au transport&quot;">​</a></h2><ol><li>Ouvrez <strong>Services aux élèves → Pointage transport</strong>, qui liste les circuits avec leur site. Cliquez sur <strong>Pointer</strong> sur le circuit concerné.</li><li>Choisissez la <strong>date</strong> et le <strong>sens</strong> du trajet — <strong>Montée</strong> ou <strong>Descente</strong> — en haut de page.</li><li>Pour chaque élève affecté au circuit, touchez <strong>Présent</strong> ou <strong>Absent</strong> — le bouton <strong>Tous présents</strong> remet toute la liste à présent.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Si aucun élève n&#39;est affecté au circuit, la page l&#39;indique. Le pointage fonctionne comme celui de la cantine (voir l&#39;encadré ci-dessus).</p>',14)])])}const f=t(a,[["render",o]]);export{d as __pageData,f as default};
